const hoje = new Date();

// 2. Calcula o mês seguinte (Se hoje for Julho/2026, vai para Agosto/2026)
const proximoMes = new Date(hoje.getFullYear(), hoje.getMonth() + 1, 1);

const ano = proximoMes.getFullYear();
const numeroMes = proximoMes.getMonth() + 1; // 1 a 12
const numeroMesStr = String(numeroMes).padStart(2, '0'); // '08', '09'...

// Nomes dos meses por extenso
const mesesPorExtenso = [
  "JANEIRO", "FEVEREIRO", "MARÇO", "ABRIL", "MAIO", "JUNHO",
  "JULHO", "AGOSTO", "SETEMBRO", "OUTUBRO", "NOVEMBRO", "DEZEMBRO"
];

const nomeMesMaiusculo = mesesPorExtenso[proximoMes.getMonth()];
const nomeMesMinusculo = nomeMesMaiusculo.toLowerCase();

// 3. Monta as variáveis finais que usaremos no fluxo
const dataPrimeiroDia = `01/${numeroMesStr}/${ano}`;            // Ex: "01/08/2026"
const nomePastaMes = `${numeroMesStr}. ${nomeMesMaiusculo} ${ano}`; // Ex: "08. AGOSTO 2026"
const textoEmpresaMes = `${nomeMesMinusculo} ${ano}`;            // Ex: "agosto 2026"

// Retorna o objeto completo para os próximos nós
return [{
  json: {
    data_primeiro_dia: dataPrimeiroDia,
    nome_pasta_mes: nomePastaMes,
    texto_empresa_mes: textoEmpresaMes,
    ano_vigente: ano,
    mes_num: numeroMes
  }
}];

