  3: 'Atende quarta?', 4: 'Atende quinta?', 5: 'Atende sexta?', 6: 'Atende sabado?'
};

// Busca os médicos direto do nó correto
const medicos = $('Trás as escalas de todos os médicos2').all().map(item => item.json);
const matrizImpressao = [];

// Roda até construir todas as semanas do mês alvo
while (dataAtual <= ultimoDiaDoMes) {
  let linhaDatas = [];
  let datasDaSemana = [];

  // 1. Cabeçalho de datas da semana (Ex: 26/07)
  for (let i = 0; i < 7; i++) {
    let diaF = String(dataAtual.getDate()).padStart(2, '0');
    let mesF = String(dataAtual.getMonth() + 1).padStart(2, '0');
    linhaDatas.push(`${diaF}/${mesF}`);
    datasDaSemana.push(new Date(dataAtual));
    dataAtual.setDate(dataAtual.getDate() + 1); // Avança 1 dia
  }
  matrizImpressao.push(linhaDatas); 

  // 2. Coleta os médicos agrupando POR DIA (empacotamento eficiente)
  let colunasDaSemana = [[], [], [], [], [], [], []];

  for (let i = 0; i < 7; i++) {
    let dataDia = datasDaSemana[i];
    let diaSemanaNum = dataDia.getDay();
    let colunaAtende = mapaDias[diaSemanaNum];

    // É do mês alvo?
    if (dataDia.getMonth() + 1 === mes) {
      medicos.forEach(medico => {
        if (medico[colunaAtende] && medico[colunaAtende].toString().trim().toLowerCase() === 'sim') {
          let nome = medico['Nome do Profissional'] || '';
          let inicio = medico['Horário Início'] || '';
          let fim = medico['Horário Fim'] || '';
          let vagas = medico['Qtd Vagas'] || '';
          let tipoAtendimento = medico['Tipo Atendimento'] || 'Consulta';

          colunasDaSemana[i].push(`${nome}\n(${vagas}) ${inicio} - ${fim}\n${tipoAtendimento}`);
        }
      });
    }
  }

  // 3. Monta as 5 linhas da semana pegando as células certas de cada coluna
  for (let rowIndex = 0; rowIndex < 5; rowIndex++) {
    let linha = [];
    for (let dayIndex = 0; dayIndex < 7; dayIndex++) {
      // Pega o médico na posição (rowIndex) daquele dia. Se não tiver, deixa vazio ""
      linha.push(colunasDaSemana[dayIndex][rowIndex] || "");
    }
    matrizImpressao.push(linha);
  }
}

return [{
  json: {
    id_sheets_escala_recem_criada: idPlanilha,
    values_impressao: matrizImpressao
  }
}];

